INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 17, 114.94, 121.52, 'It was a new experience, but it was a lot of fun doing it together with your classmates.', '虽然是个新鲜的体验，但和同学们一起熬夜倒也挺有意思的。', '/ɪt wʌz ə nuː ɪkˈspɪriəns bʌt ɪt wʌz ə lɑt əv fʌn ˈduɪŋ ɪt təˈɡɛðər wɪð jɔːr ˈklæsmeɪts/', '<span>It</span> <span>was</span> <span>a</span> <span>new</span> <span>experience,</span> <span>but</span> <span>it</span> <span>was</span> <span>a</span> <span>lot</span> <span>of</span> <span>fun</span> <span>doing</span> <span>it</span> <span>together</span> <span>with</span> <span>your</span> <span>classmates.</span>'
