INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 23, 146.86, 150.8, 'And that''s when I started feeling like an engineer.', '从那一刻起，我开始感觉自己像个工程师。', '/ænd ðæts wɛn aɪ ˈstɑːrtɪd ˈfiːlɪŋ laɪk ən ɛndʒəˈnɪr/', '<span>And</span> <span>that''s</span> <span>when</span> <span>I</span> <span>started</span> <span>feeling</span> <span>like</span> <span>an</span> <span>engineer.</span>'
