INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 24, 150.8, 160.42, 'One of the best parts of MIT is actually UROP the opportunity as an undergraduate to work on real research.', '麻省理工学院最棒的一点就是 UROP 项目 它让本科生有机会参与真正的科研工作。', '/wʌn əv ðə bɛst pɑːrts əv maɪt ɪz ˈækʃuəli ˈjʊrɑp ði ˌɑːpərˈtuːnəti æz ən ˌʌndərˈɡrædʒuət tu wɜːrk ɑn riəl rɪˈsɜːrtʃ/', '<span>One</span> <span>of</span> <span>the</span> <span>best</span> <span>parts</span> <span>of</span> <span>MIT</span> <span>is</span> <span>actually</span> <span>UROP</span> <span>the</span> <span>opportunity</span> <span>as</span> <span>an</span> <span>undergraduate</span> <span>to</span> <span>work</span> <span>on</span> <span>real</span> <span>research.</span>'
