INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 25, 160.42, 163.68, 'And that actually truly changed my life.', '这确实彻底改变了我的生活。', '/ænd ðæt ˈækʃuəli ˈtruːli tʃeɪndʒd maɪ laɪf/', '<span>And</span> <span>that</span> <span>actually</span> <span>truly</span> <span>changed</span> <span>my</span> <span>life.</span>'
