INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 35, 222.88, 226.58, 'I was part of a team trying to discover something new.', '而是成为了试图探索新事物的团队中的一员。', '/aɪ wʌz pɑːrt əv ə tiːm ˈtraɪɪŋ tu dɪˈskʌvər ˈsʌmθɪŋ nuː/', '<span>I</span> <span>was</span> <span>part</span> <span>of</span> <span>a</span> <span>team</span> <span>trying</span> <span>to</span> <span>discover</span> <span>something</span> <span>new.</span>'
