INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 36, 226.58, 229.8, 'And I remember thinking, "Wow.', '我记得当时心想：“哇。', '/ænd aɪ rɪˈmɛmbər ˈθɪŋkɪŋ wɑʊ/', '<span>And</span> <span>I</span> <span>remember</span> <span>thinking,</span> <span>"Wow.</span>'
