INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 37, 229.8, 242.125, 'We can build things this small, things tiny enough to fit on a die the size of a coin but powerful enough to change the world.', '我们可以制造如此小的东西——小到能放在一枚硬币大小的芯片上， 却强大到足以改变世界。', '/wi kæn bɪld ˈθɪŋz ðɪs smɔːl ˈθɪŋz ˈtaɪni ɪˈnʌf tu fɪt ɑn ə daɪ ðə saɪz əv ə kɔɪn bʌt ˈpaʊərfəl ɪˈnʌf tu tʃeɪndʒ ðə wɜːrld/', '<span>We</span> <span>can</span> <span>build</span> <span>things</span> <span>this</span> <span>small,</span> <span>things</span> <span>tiny</span> <span>enough</span> <span>to</span> <span>fit</span> <span>on</span> <span>a</span> <span>die</span> <span>the</span> <span>size</span> <span>of</span> <span>a</span> <span>coin</span> <span>but</span> <span>powerful</span> <span>enough</span> <span>to</span> <span>change</span> <span>the</span> <span>world.</span>'
FROM episodes e WHERE e.video_id = 'RauETW1YDGU5AeY';
INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 38, 242.125, 247.0, '" And that''s when I fell in love with semiconductors.', '”那一刻，我彻底爱上了半导体。', '/ænd ðæts wɛn aɪ fɛl ɪn lʌv wɪð ˈsɛmikənˌdʌktərz/', '<span>"</span> <span>And</span> <span>that''s</span> <span>when</span> <span>I</span> <span>fell</span> <span>in</span> <span>love</span> <span>with</span> <span>semiconductors.</span>'
