INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 46, 304.88, 313.0, 'Not the confidence that I would always know the answer but the confidence that even when I didn''t know the answer', '不是那种总知道答案的自信， 而是那种即便我不知道答案时的自信。', '/nɑt ðə ˈkɑnfɪdəns ðæt aɪ wʊd ˈɔlweɪz noʊ ði ˈænsər bʌt ðə ˈkɑnfɪdəns ðæt ˈivən wɛn aɪ dɪdnt noʊ ði ˈænsər/', '<span>Not</span> <span>the</span> <span>confidence</span> <span>that</span> <span>I</span> <span>would</span> <span>always</span> <span>know</span> <span>the</span> <span>answer</span> <span>but</span> <span>the</span> <span>confidence</span> <span>that</span> <span>even</span> <span>when</span> <span>I</span> <span>didn''t</span> <span>know</span> <span>the</span> <span>answer</span>'
FROM episodes e WHERE e.video_id = 'RauETW1YDGU5AeY';
INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 47, 313.0, 314.74, 'I could figure it out.', '我能弄明白。', '/aɪ kʊd ˈfɪɡjər ɪt aʊt/', '<span>I</span> <span>could</span> <span>figure</span> <span>it</span> <span>out.</span>'
