INSERT INTO subtitles (id, episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM subtitles), e.id, 11, 113.07, 120.8, 'guys will always be in my heart and i sincerely sincerely appreciate it no words can describe how i feel about you guys and', '那些人永远留在我的心中。 真心地感谢你们。无法用言语来表达我对你们所有人的感激之情。', '/ɡaɪz wɪl ˈɔːlweɪz biː ɪn maɪ hɑːrt ænd aɪ ˈsɪnsɪrli ˈsɪnsɪrli æpriːʃieɪt ɪt noʊ wɜːrdz kæn dɪˈskraɪb haʊ aɪ fiːl əˈbaʊt juː ɡaɪz ænd/', '<span>guys</span> <span>will</span> <span>always</span> <span>be</span> <span>in</span> <span>my</span> <span>heart</span> <span>and</span> <span>i</span> <span>sincerely</span> <span>sincerely</span> <span>appreciate</span> <span>it</span> <span>no</span> <span>words</span> <span>can</span> <span>describe</span> <span>how</span> <span>i</span> <span>feel</span> <span>about</span> <span>you</span> <span>guys</span> <span>and</span>'
